def _emoji_elements() -> frozenset[str]:
    padding = "=" * (-len(_PACKED) % 4)
    raw = zlib.decompress(base64.urlsafe_b64decode(_PACKED + padding)).decode("utf-8")
    values = frozenset(raw.split())
    if "" in values or len(values) != 2334:
        raise RuntimeError("Pinned TDLib emoji table is corrupt")
    return values


_EMOJI_ELEMENTS = _emoji_elements()


def _is_element(value: str) -> bool:
    encoded = value.encode("utf-8")
    if len(encoded) > _MAX_EMOJI_BYTES + 3:
        return False
    if value in _EMOJI_ELEMENTS:
        return True
    if not value.endswith("\ufe0f") or value.endswith("\ufe0f\ufe0f"):
        return False
    return value[:-1] in _EMOJI_ELEMENTS


def is_single_emoji(value: str) -> bool:
    """Return the pinned local TDLib-policy result for one covered string."""
    return all(_is_element(part) for part in value.split("\u200d"))
